-- Transaction-only metadata fixtures. No hosted object is uploaded or removed.
begin;
set local statement_timeout='60s';
select set_config('t022.user',gen_random_uuid()::text,true),set_config('t022.session',gen_random_uuid()::text,true),set_config('t022.image',gen_random_uuid()::text,true),set_config('t022.capture',gen_random_uuid()::text,true),set_config('t022.lease',gen_random_uuid()::text,true),set_config('t022.orphan',gen_random_uuid()::text,true);
create function pg_temp.drive_assert(ok boolean,message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'Drive attachments/cleanup: %',message;end if;end $$;
create function pg_temp.drive_error(command text,expected text) returns void language plpgsql as $$ declare actual text;detail text;context text;begin begin execute command;exception when others then get stacked diagnostics actual=returned_sqlstate,detail=message_text,context=pg_exception_context;if actual<>expected then raise exception 'Expected %, got %: % / %',expected,actual,detail,left(context,400);end if;return;end;raise exception 'Expected %, succeeded',expected;end $$;
create function pg_temp.image() returns jsonb language sql as $$ select jsonb_build_object('id',current_setting('t022.image'),'user_id',current_setting('t022.user'),'kind','capture_image','folder_id',null,'name','Image.png','mime','image/png','bytes',10,'sha256',repeat('a',64),'width',20,'height',40,'starred',false,'deleted_at',null,'deletion_batch_id',null,'created_at',now()-interval '2 days','updated_at',now()-interval '2 days','modified_at',now()-interval '2 days');$$;
create function pg_temp.attachment() returns jsonb language sql as $$ select jsonb_build_object('id',current_setting('t022.image'),'name','Image.png','mime','image/png','bytes',10,'width',20,'height',40);$$;
create function pg_temp.capture() returns jsonb language sql as $$ select jsonb_build_object('id',current_setting('t022.capture'),'user_id',current_setting('t022.user'),'client_id','capture-with-image','type','note','title','Imagem privada','content','Nota','status','inbox','category_id',null,'project_id',null,'converted_task_id',null,'captured_at',now(),'organized_at',null,'archived_at',null,'deleted_at',null,'created_at',now(),'updated_at',now(),'attachments',jsonb_build_array(pg_temp.attachment()));$$;
create function pg_temp.capture_event(before_row jsonb,after_row jsonb) returns void language plpgsql as $$ declare e jsonb;begin e:=jsonb_build_object('id',gen_random_uuid(),'user_id',current_setting('t022.user'),'entity_type','capture','entity_id',current_setting('t022.capture'),'action',case when before_row is null then 'created' else 'updated' end,'canal','web','occurred_at',now(),'before',before_row,'after',after_row);insert into public.domain_events(id,user_id,entity_type,entity_id,action,canal,occurred_at,before,after,capture_task_payload) values((e->>'id')::uuid,(e->>'user_id')::uuid,'capture',(e->>'entity_id')::uuid,e->>'action','web',now(),before_row,after_row,e);end $$;
do $$ declare schema_name text;begin perform pg_temp.drive_assert(current_user='postgres','owner required');select nspname into schema_name from pg_namespace where oid=pg_my_temp_schema();execute format('grant usage on schema %I to service_role',schema_name);execute format('grant execute on all functions in schema %I to service_role',schema_name);end $$;
insert into auth.users(id,aud,role,email,is_anonymous,created_at,updated_at) values(current_setting('t022.user')::uuid,'authenticated','authenticated','t022-'||current_setting('t022.user')||'@example.invalid',false,now(),now());
insert into auth.sessions(id,user_id,created_at,updated_at) values(current_setting('t022.session')::uuid,current_setting('t022.user')::uuid,now(),now());
set local role service_role;
select public.file_upload_reserve(current_setting('t022.user')::uuid,current_setting('t022.session')::uuid,'capture_image','Image.png',null,'image-reserve',current_setting('t022.image')::uuid,1000,1048576,now()+interval '150 minutes');
select public.file_upload_claim(current_setting('t022.user')::uuid,current_setting('t022.session')::uuid,current_setting('t022.image')::uuid,current_setting('t022.lease')::uuid,'image-finalize');
select public.file_upload_complete(current_setting('t022.user')::uuid,current_setting('t022.session')::uuid,current_setting('t022.image')::uuid,current_setting('t022.lease')::uuid,'image-finalize',pg_temp.image(),1048576);
select public.file_upload_reserve(current_setting('t022.user')::uuid,current_setting('t022.session')::uuid,'drive','Abandoned.txt',null,'abandoned',current_setting('t022.orphan')::uuid,1000,1048576,now()+interval '150 minutes');
reset role;
select app_private.capture_task_validate_payload('capture',pg_temp.capture());
select pg_temp.drive_error(format('select app_private.capture_task_validate_payload(''capture'',%L::jsonb)',jsonb_set(pg_temp.capture(),'{attachments}',jsonb_build_array(pg_temp.attachment(),pg_temp.attachment()))::text),'23514');
select pg_temp.drive_error(format('select app_private.capture_task_validate_payload(''capture'',%L::jsonb)',jsonb_set(pg_temp.capture(),'{attachments}',jsonb_build_array(pg_temp.attachment()||'{"bytes":99}'::jsonb))::text),'23514');
select pg_temp.drive_error(format('select app_private.capture_task_validate_payload(''capture'',%L::jsonb)',jsonb_set(pg_temp.capture(),'{attachments}',(select jsonb_agg(pg_temp.attachment()) from generate_series(1,7)))::text),'22023');
insert into public.captures(id,user_id,client_id,payload,status,created_at,updated_at) values(current_setting('t022.capture')::uuid,current_setting('t022.user')::uuid,'capture-with-image',pg_temp.capture(),'inbox',now(),now());
select pg_temp.capture_event(null,pg_temp.capture());
select pg_temp.drive_assert(exists(select 1 from public.capture_file_links where capture_id=current_setting('t022.capture')::uuid and file_id=current_setting('t022.image')::uuid),'capture stores verified relation');
update app_private.upload_reservations r set expires_at=now()-interval '1 minute' where r.user_id=current_setting('t022.user')::uuid;
set local role service_role;
do $$ declare candidates jsonb;begin candidates:=public.file_cleanup_candidates();perform pg_temp.drive_assert(exists(select 1 from jsonb_array_elements(candidates) c where c->>'id'=current_setting('t022.image') and c->'remove_final'='false'::jsonb),'linked final retained');perform pg_temp.drive_assert(exists(select 1 from jsonb_array_elements(candidates) c where c->>'id'=current_setting('t022.orphan') and c->'remove_final'='true'::jsonb),'abandoned final/stage cleanup');perform public.file_cleanup_ack(current_setting('t022.image')::uuid);perform public.file_cleanup_ack(current_setting('t022.orphan')::uuid);perform public.file_cleanup_ack(current_setting('t022.orphan')::uuid);perform pg_temp.drive_assert(public.file_cleanup_candidates()='[]'::jsonb,'repeat skips linked old image and cleaned orphan');end $$;
reset role;
update public.captures c set payload=jsonb_set(c.payload,'{attachments}','[]'::jsonb) where c.id=current_setting('t022.capture')::uuid;
select pg_temp.capture_event(pg_temp.capture(),jsonb_set(pg_temp.capture(),'{attachments}','[]'::jsonb));
set local role service_role;
do $$ declare candidates jsonb;begin candidates:=public.file_cleanup_candidates();perform pg_temp.drive_assert(jsonb_array_length(candidates)=1 and candidates->0->>'id'=current_setting('t022.image') and candidates->0->'remove_final'='true'::jsonb,'unlinked old image scheduled');perform pg_temp.drive_assert(public.drive_snapshot(current_setting('t022.user')::uuid,current_setting('t022.session')::uuid,'read.drive',1048576,1000)->>'usage_bytes'='10','quota retained before Storage acknowledgment');perform public.file_cleanup_ack(current_setting('t022.image')::uuid);perform pg_temp.drive_assert(public.drive_snapshot(current_setting('t022.user')::uuid,current_setting('t022.session')::uuid,'read.drive',1048576,1000)->>'usage_bytes'='0','quota released after acknowledgment');perform pg_temp.drive_assert(public.file_cleanup_candidates()='[]'::jsonb,'purge idempotent');end $$;
rollback;
